import { test, expect, type Locator } from '@playwright/test';
import path from 'node:path';

test.use({ storageState: path.join(__dirname, '../../../auth/user.json') });

interface Row {
  time: string;
  duration: string;
  events: string;
  icon: string;
  text: string;
}

// Убираем маркеры направления текста (RLM/LRM/изоляты), чтобы сравнивать чистый текст.
const clean = (s: string) => s.replace(/[‎‏⁦-⁩]/g, '').replace(/\s+/g, ' ').trim();

async function readRows(rows: Locator, count: number): Promise<Row[]> {
  const raw = await rows.evaluateAll(
    (els, n) =>
      els.slice(0, n).map((el) => ({
        text: (el as HTMLElement).innerText,
        icon: el.querySelector('svg path')?.getAttribute('d') ?? '',
      })),
    count,
  );
  return raw.map(({ text, icon }) => {
    const t = clean(text);
    return {
      text: t,
      icon,
      time: t.match(/(\d{1,2}:\d{2})/)?.[1] ?? '',
      duration: t.match(/(\d+)\s*דק׳/)?.[1] ?? '',
      events: t.match(/(בלי אירועים|כשל אחד|\d+ כשלים|התרעה אחת|\d+ התרעות)\s*$/)?.[1] ?? '',
    };
  });
}

test.describe('Главная — «ניטורים אחרונים» совпадает с «היסטוריה»', () => {
  test('«ניטורים אחרונים» на בית: три строки = три первые записи «היסטוריה» (текст и иконка), без «בלי התרעות» у сбоя #09b2de78 @iphone @prod-safe', async ({ page }) => {
    // 1. Open /home, wait for the "ניטורים אחרונים" block and exactly 3 session rows (+ "הכל" link)
    await page.goto('/home');
    await expect(page.getByRole('heading', { name: 'ניטורים אחרונים' })).toBeVisible();
    const homeRows = page.getByRole('button', { name: /דק׳ · / });
    await expect(homeRows).toHaveCount(3);
    await expect(page.getByRole('link', { name: 'הכל' }).last()).toBeVisible();

    // 2. Record text and icon of each of the 3 rows
    const home = await readRows(homeRows, 3);
    for (const r of home) {
      expect(r.text).toMatch(/(היום|אתמול|[א-ת]+.*), \d{1,2}:\d{2}\s+\d+ דק׳ · .+/);
      expect(r.events, `события в строке «${r.text}»`).not.toBe('');
      expect(r.icon).not.toBe('');
    }

    // 3. Open /history (tab "היסטוריה"), wait for the first records and record them
    await page.getByRole('tab', { name: 'היסטוריה' }).click();
    await expect(page).toHaveURL(/\/history/);
    const historyRows = page.getByRole('button', { name: /דק׳ ניטור/ });
    await expect(historyRows.nth(3)).toBeVisible();
    const history = await readRows(historyRows, 4);

    // Допускается сдвиг ровно на одну новую запись сверху (параллельный тест создал сеанс)
    const shift = history[0].time === home[0].time ? 0 : 1;
    if (shift === 1) expect(history[1].time).toBe(home[0].time);
    const top = history.slice(shift, shift + 3);

    for (let i = 0; i < 3; i++) {
      expect(top[i].time, `время старта строки ${i + 1}`).toBe(home[i].time);
      expect(top[i].duration, `длительность строки ${i + 1}`).toBe(home[i].duration);
      expect(top[i].events, `события строки ${i + 1}`).toBe(home[i].events);
      expect(top[i].icon, `иконка строки ${i + 1}`).toBe(home[i].icon);
    }

    // Строка со сбоем: «כשל»/«כשלים» и иконка не равна иконке «בלי אירועים»
    const noEventsIcon = home.find((r) => r.events === 'בלי אירועים')?.icon;
    for (const r of home.filter((x) => /כשל/.test(x.events))) {
      expect(r.text).toMatch(/כשל/);
      if (noEventsIcon) expect(r.icon).not.toBe(noEventsIcon);
    }

    // 4. Back to /home, press "הכל" in "ניטורים אחרונים"
    await page.getByRole('tab', { name: 'בית' }).click();
    await expect(page).toHaveURL(/\/home/);
    const recentHeading = page.getByRole('heading', { name: 'ניטורים אחרונים' });
    await expect(recentHeading).toBeVisible();
    // Текст «בלי התרעות» в блоке не встречается
    await expect(page.getByText('בלי התרעות')).toHaveCount(0);
    // «הכל» блока «ניטורים אחרונים» — нижняя из двух ссылок «הכל» (вторая — у «הטלפונים»)
    await page.getByRole('link', { name: 'הכל' }).last().click();
    await expect(page).toHaveURL(/\/history/);
  });
});
